package wallet

import (
	"errors"
	"fmt"
)

// Account holds a user's balance in cents.
type Account struct {
	ID      string
	Owner   string
	Balance int64
}

var ErrInsufficient = errors.New("insufficient funds")

// Withdraw removes amount cents from the account balance.
func (a *Account) Withdraw(amount int64) error {
	if amount <= 0 {
		return fmt.Errorf("invalid amount: %d", amount)
	}
	if a.Balance < amount {
		return ErrInsufficient
	}
	a.Balance -= amount
	return nil
}

// Transfer moves amount cents from src to dst.
func Transfer(src, dst *Account, amount int64) error {
	if err := src.Withdraw(amount); err != nil {
		return err
	}
	dst.Balance += amount
	return nil
}

